pub enum Zone {
    #[default]
    Default = 0,
    DeckTop = 1,
    DeckBottom = 2,
    Energy = 3,
    Stage = 4,
    Deck = 5,
    Hand = 6,
    Discard = 7,
    LiveSet = 13,
    SuccessPile = 16,
    Yell = 17,
}

pub fn get_group_name(id: u8, lang: &str) -> &'static str {
    match lang {
        "jp" => match id {
            0 => "μ's",
            1 => "Aqours",
            2 => "虹ヶ咲学園スクールアイドル同好会",
            3 => "Liella!",
            4 => "蓮ノ空女学院スクールアイドルクラブ",
            10 => "A-RISE",
            11 => "Saint Snow",
            12 => "Sunny Passion",
            13 => "スクールアイドルミュージカル",
            99 => "その他",
            100 => "-",
            _ => "-",
        },
        _ => match id {
            0 => "μ's",
            1 => "Aqours",
            2 => "Nijigasaki High School Idol Club",
            3 => "Liella!",
            4 => "Hasunosora Girls' High School Idol Club",
            10 => "A-RISE",
            11 => "Saint Snow",
            12 => "Sunny Passion",
            13 => "School Idol Musical",
            99 => "Other",
            100 => "-",
            _ => "-",
        }
    }
}

